import React, { useEffect, useState } from 'react'
import { useParams, Link } from 'react-router-dom';
import './Stream.css';
import Footer from './Footer';
import { Helmet } from 'react-helmet';
import { Api, Popular } from './Api'

const Stream = () => {

  const value = useParams().type;

  const [anime, setAnime] = useState({});

  const [anify, setanify] = useState([]);

  const [anifyep, setanifyep] = useState("0")

  const [videos, setvideos] = useState('');

  const [server, setserver] = useState("1");

  const [episode, setepisode] = useState([]);

  const [num, setnum] = useState("1");

  const [select, setselect] = useState("1");

  const [dataanify, setdataanify] = useState("one piece");

  useEffect(() => {
    getanime();
  }, [anifyep, value]);

  const getanime = async () => {
    await fetch(`https://api.jikan.moe/v4/anime/${value}`)
      .then((res) => {
        return res.json();
      })
      .then((data) => {
        const { title, title_english, title_japanese, synopsis, episodes, type, rank, season, year } = data.data;

        setdataanify(title);

        const detail = {
          title,
          title_english,
          title_japanese,
          synopsis,
          episodes,
          type,
          rank,
          season,
          year
        };
        setAnime(detail);
      });
  };

  useEffect(() => {
    getanify();
  }, [anime, server, anifyep, dataanify]);

  const getanify = async () => {
    await fetch(`https://api.anify.tv/search?type=anime&query=${dataanify}&page=1`)
      .then((res) => {
        return res.json();
      })
      .then((data) => {
        setanify(data.results[0].episodes.data[1].episodes[anifyep].id);
      });
  };

  // making iframe src with replace method
  useEffect(() => {
    Server();
  }, [server, num, anime, anify])
  const Server = () => {
    if (server === "1") {
      let video = `${anime.title}`;
      video = video.replace(/[:()/]/g, '').replace(/[' ']/g, '-');
      video = `https://player.ryuk.to?id=${video}-episode-${num}`;
      setvideos(video);
    } if (server === "2") {
      let video = `${anify}`;
      video = video.replace(/[:()/]/g, '').replace(/[' ']/g, '-');
      video = `https://player.ryuk.to?id=${video}`;
      setvideos(video);
    } else {
      let video = `${anime.title_english}`;
      video = video.replace(/[:()/]/g, '').replace(/[' ']/g, '-');
      video = `https://player.ryuk.to?id=${video}-episode-${num}`;
      setvideos(video);
    }
  }

  // making episodes
  useEffect(() => {
    setepisode(num => {
      const newnum = Array(anime.episodes).fill().map((item, index) => index + 1);
      return [...newnum];
    });
  }, [anime.episodes])

  // Changing episode button state
  const epistate = (e) => {
    setnum(e.target.value);
    setanifyep(e.target.value - 1)
    setselect(e.target.value);
  };

  return (
    <div style={{ backgroundColor: "#201F31" }}>
      <Helmet>
        <title>Aniature - Watch {`${anime.title}`} for free</title>
        <meta
          name="description"
          content={`Watch ${anime.title} for free in aniature. All episode are free and other anime also free in english subbed`}
        />
        <meta
          name="keywords"
          content={`POkemon, demon slayer, attack on titan, spy x family, naruto, naruto shippuden, english subbed, hindi, download, full episode, ${anime.title},`}
        />
      </Helmet>
      <div className='container text-center pt-4'>
        <div className='d-flex row stream-flex'>
          <div className='video-conatiner col'>
            <iframe title={videos} className='anivid' src={videos} frameborder="0" allowFullScreen="true"></iframe>
            <p className='color text-light text-center'>You are watching episode {num} of {anime.title}</p>
            <p className='color text-light text-center' style={{ backgroundColor: "#2B2A3C", borderRadius: "10px", padding: "2px" }}>If current server doesn't work please try other servers beside. And if any problem occurs please refresh page. Some anime can't play. Enjoy your's anime.</p>
            <div className='server'>
              <button className='epivid color' onClick={() => setserver("1")} style={{ backgroundColor: server === "1" ? '#FFBADE' : '#2B2A3C', color: server === "1" ? 'black' : 'white', fontWeight: 600 }}>Server 1</button>
              <button className='epivid color' onClick={() => setserver("2")} style={{ backgroundColor: server === "2" ? '#FFBADE' : '#2B2A3C', color: server === "2" ? 'black' : 'white', fontWeight: 600 }}>Server 2</button>
              <button className='epivid color' onClick={() => setserver("3")} style={{ backgroundColor: server === "3" ? '#FFBADE' : '#2B2A3C', color: server === "3" ? 'black' : 'white', fontWeight: 600 }}>Server 3</button>
            </div>
            <h5 className='text-light d-flex m-3'>All Episodes :</h5>
            {
              episode.length && episode.map((ele) => {
                return (
                  <div className='epilist' key={ele}>
                    <button onClick={epistate} value={ele} className='epivid color' style={{ backgroundColor: ele == select ? "#FFBADE" : "#2B2A3C", color: ele == select ? "black" : "white", fontWeight: 600 }}>{ele}</button>
                  </div>
                )
              })
            }
            <p style={{ backgroundColor: '#2B2A3C', padding: '15px', borderRadius: '5px' }} className='color text-light mt-4'>{anime.synopsis}</p>

            <div
              className='recommanded'
              style={{
                textAlign: 'start'
              }}>
              <h2 style={{
                color: "#FFBADE"
              }}>Recommanded For You</h2>

              <div className='animes'>
                {Api.map((ele) => {
                  return (
                    <>
                      <div className="card mt-3" key={ele.id}>
                        <Link style={{ textDecoration: 'none' }} to={ele.link}>
                          <img src={ele.img2} className="card-img-top" alt="loading..." />
                          <p style={{
                            margin: 0,
                            padding: '5px 10px',
                            position: 'absolute',
                            top: 0,
                            right: 0,
                            backgroundColor: 'white',
                            borderRadius: '0 0 0 6px',
                            color: 'black',
                            fontWeight: 500
                          }} className='trending-no'>{ele.id}</p>
                          <div style={{
                            margin: 0,
                            backgroundColor: 'white',
                            fontWeight: 500,
                            padding: '10px',
                            borderRadius: '0 0 7px 7px',
                            height: '40px'
                          }}
                            className="card-body">
                            <p className="card-text text-dark text-center">{ele.name}</p>
                          </div>
                        </Link>
                      </div>
                    </>
                  )
                })}
              </div>

            </div>

          </div>

          <div className='col'>
            <div style={{
              backgroundColor: '#2B2A3C',
              padding: '15px',
              borderRadius: '5px'
            }} className='video-detail'>
              <p className='color'>Title: <span className='detail text-light'>{anime.title}</span></p>
              <p className='color'>Title japanese: <span className='detail text-light'>{anime.title_japanese}</span></p>
              <p className='color'>Type: <span className='detail text-light'>{anime.type}</span></p>
              <p className='color'>Episodes: <span className='detail text-light'>{anime.episodes}</span></p>
              <p className='color'>Rank: <span className='detail text-light'>{anime.rank}</span></p>
              <p className='color'>Season: <span className='detail text-light'>{anime.season}</span></p>
              <p className='color'>Year: <span className='detail text-light'>{anime.year}</span></p>
            </div>

            <h2 style={{
              textAlign: 'start',
              color: '#FFBADE',
              marginBottom: '30px'
            }}>Most Popular</h2>

            <div style={{
              display: 'flex',
              flexFlow: 'row wrap',
              marginBottom: '40px',
              width: '100%',
              justifyContent: 'space-between',
              gap: '10px',
              backgroundColor: '#2B2A3C',
              padding: '10px 15px',
              borderRadius: '3px'
            }}>
              {
                Popular.map((ele) => (
                  <div key={ele.id} className='video-details' style={{
                    display: 'flex',
                    flexFlow: 'row',
                    gap: '8px'
                  }}>
                    <p style={{
                      fontSize: '16px',
                      color: 'white',
                      margin: 0
                    }}>0{ele.id}</p>
                    <div style={{
                      display: 'flex',
                      gap: '15px',
                      alignItems: 'center'
                    }}>
                      <img
                        src={ele.img}
                        alt="..."
                        style={{
                          height: '2.5cm',
                          width: '2cm'
                        }} />
                      <div style={{
                        textAlign: 'start'
                      }}>
                        <p style={{
                          color: 'white',
                          fontWeight: 600,
                          fontSize: '15px',
                          textTransform: 'capitalize'
                        }}>{ele.title}</p>
                        <div style={{
                          display: 'flex',
                          gap: '15px'
                        }}>
                          <p style={{
                            backgroundColor: '#B9E7FF',
                            color: 'black',
                            padding: '2px 5px'
                          }}><i className="ri-mic-fill"></i> {ele.mic}</p>
                          <li style={{ color: 'white' }}>tv</li>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              }
            </div>
          </div>
        </div>

        <div
          className='recommandeds'
          style={{
            textAlign: 'start'
          }}>
          <h2 style={{
            color: "#FFBADE"
          }}>Recommanded For You</h2>

          <div className='animes'>
            {Api.map((ele) => {
              return (
                <>
                  <div className="card mt-3" key={ele.id}>
                    <Link style={{ textDecoration: 'none' }} to={ele.link}>
                      <img src={ele.img2} className="card-img-top" alt="loading..." />
                      <p style={{
                        margin: 0,
                        padding: '5px 10px',
                        position: 'absolute',
                        top: 0,
                        right: 0,
                        backgroundColor: 'white',
                        borderRadius: '0 0 0 6px',
                        color: 'black',
                        fontWeight: 500
                      }} className='trending-no'>{ele.id}</p>
                      <div style={{
                        margin: 0,
                        backgroundColor: 'white',
                        fontWeight: 500,
                        padding: '10px',
                        borderRadius: '0 0 7px 7px',
                        height: '40px'
                      }}
                        className="card-body">
                        <p className="card-text text-dark text-center">{ele.name}</p>
                      </div>
                    </Link>
                  </div>
                </>
              )
            })}
          </div>

        </div>

        <Footer />
      </div>
    </div>
  )
}

export default Stream;
