import React from 'react'
import './Anilist.css';
import { useParams } from 'react-router-dom';
import { useState, useEffect } from 'react';
import Footer from './Footer';
import { Link } from 'react-router-dom';
import { Popular } from './Api'

const Search = (props) => {

  const value = useParams().type;

  const [anime, setAnime] = useState([]);

  useEffect(() => {
    getanime();
  }, [value]);

  const getanime = async () => {
    await fetch(`https://api.jikan.moe/v4/anime?q=${value}`)
      .then((res) => {
        return res.json();
      })
      .then((data) => {
        setAnime(data.data);
      });
  };

  return (
    <div style={{ backgroundColor: "#201F31" }}>
      <div className='container-fluid'>
        <div className='anime-box'>
          <div className='trending d-flex mb-2'>
            <h2 style={{color: '#FFBADE', textTransform: 'capitalize', margin: '0', padding: '0'}}>{value}</h2>
          </div>
          <div className='anime'>
            {anime.length ? anime.map((ele, index) => {
              return (
                <>
                  <div 
                  className="card mt-3"
                   key={ele.mal_id}>
                    <Link style={{ textDecoration: "none" }} to={{
                      pathname: `/stream/${ele.mal_id}`
                    }}><img src={ele.images.jpg.large_image_url} className="card-img-top" alt="loading..." />
                      <div style={{
                        margin: 0,
                        backgroundColor: 'white',
                        fontWeight: 500,
                        padding: '10px',
                        borderRadius: '0 0 7px 7px'
                      }}
                        className="card-body">
                        <p className="card-text text-dark text-center">{ele.title}</p>
                      </div></Link>
                  </div>
                </>
              )
            }) : <p className='text-primary'>Loading...</p>}
          </div>
        </div>

        <h2 style={{
              textAlign: 'start',
              color: '#FFBADE',
              marginBottom: '30px'
            }}>Most Popular</h2>

            <div style={{
              display: 'flex',
              flexFlow: 'row wrap',
              marginBottom: '40px',
              width: '100%',
              justifyContent: 'start',
              gap: '10px',
              backgroundColor: '#2B2A3C',
              padding: '10px, 15px',
              borderRadius: '3px'
            }}>
              {
                Popular.map((ele) => (
                  <div key={ele.id} className='video-details' style={{
                    display: 'flex',
                    flexFlow: 'row',
                    gap: '8px'
                  }}>
                    <p style={{
                      fontSize: '16px',
                      color: 'white',
                      margin: 0
                    }}>0{ele.id}</p>
                    <div style={{
                      display: 'flex',
                      gap: '15px',
                      alignItems: 'center'
                    }}>
                      <img
                        src={ele.img}
                        alt="..."
                        style={{
                          height: '2.5cm',
                          width: '2cm'
                        }} />
                      <div style={{
                        textAlign: 'start'
                      }}>
                        <p style={{
                          color: 'white',
                          fontWeight: 600,
                          fontSize: '15px',
                          textTransform: 'capitalize'
                        }}>{ele.title}</p>
                        <div style={{
                          display: 'flex',
                          gap: '15px'
                        }}>
                          <p style={{
                            backgroundColor: '#B9E7FF',
                            color: 'black',
                            padding: '2px 5px'
                          }}><i className="ri-mic-fill"></i> {ele.mic}</p>
                          <li style={{ color: 'white' }}>tv</li>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              }
            </div>

        <Footer />

      </div>
    </div>
  )
}

export default Search;
